#!/usr/bin/env bash
# Regenerate the committed G.722 golden vectors.
#
# The vectors are generated by ffmpeg, which carries an independent ITU-derived
# G.722 implementation. They are an interoperability baseline: the firmware codec
# must reproduce these bitstreams byte-for-byte. They are NOT the ITU official
# conformance vectors (see README.md).
#
# Run this only when intentionally changing the vector set, then commit the new
# files together with the updated checksums in SHA256SUMS.
set -euo pipefail

TESTDIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
VECTORS="$TESTDIR/vectors"
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

if ! command -v ffmpeg >/dev/null 2>&1; then
    printf 'ffmpeg not found; it is required to regenerate the vectors\n' >&2
    exit 1
fi

mkdir -p "$VECTORS"

# 10 frames at 20 ms each = 200 ms = 3200 mono samples at 16 kHz.
# Amplitude 12000 keeps the codec clear of saturation on every tone.
SAMPLES=3200
RATE=16000

for spec in "1000:sine_1k" "300:sine_300" "4000:sine_4k"; do
    hz="${spec%%:*}"
    name="${spec##*:}"
    printf 'generating %s (%s Hz)\n' "$name" "$hz"

    # Deterministic tone: integer sine, rounded, little-endian 16-bit mono.
    python3 - "$WORK/$name.pcm" "$hz" "$SAMPLES" "$RATE" <<'PY'
import math, struct, sys
path, hz, samples, rate = sys.argv[1], float(sys.argv[2]), int(sys.argv[3]), int(sys.argv[4])
with open(path, 'wb') as f:
    for i in range(samples):
        f.write(struct.pack('<h', int(round(12000 * math.sin(2 * math.pi * hz * i / rate)))))
PY

    ffmpeg -hide_banner -loglevel error -y \
        -f s16le -ar "$RATE" -ac 1 -i "$WORK/$name.pcm" \
        -c:a g722 -b:a 64k \
        -flags +bitexact -fflags +bitexact \
        "$VECTORS/$name.g722"

    cp "$WORK/$name.pcm" "$VECTORS/$name.pcm"
done

( cd "$VECTORS" && shasum -a 256 *.pcm *.g722 > SHA256SUMS )
printf '\nwrote %s\n' "$VECTORS"
cat "$VECTORS/SHA256SUMS"
